// new URL() ist im Sandbox dieser Instanz unzuverlaessig -> Regex-Parsing.
function hostOf(u){ const m = String(u||'').match(/^https?:\/\/([^\/?#]+)/i); return m ? m[1].toLowerCase().replace(/^www\./,'') : ''; }
function pathOf(u){ const m = String(u||'').match(/^https?:\/\/[^\/?#]+([^?#]*)/i); return m ? m[1].toLowerCase() : ''; }
function norm(url){ const h = hostOf(url); const p = pathOf(url); let uh = h ? (h + p) : String(url).toLowerCase().trim(); while(uh.endsWith('/')) uh = uh.slice(0,-1); return uh; }
function tnorm(t){ return String(t).toLowerCase().replace(/[^a-z0-9\u00e4\u00f6\u00fc\u00df ]/g,' ').replace(/ +/g,' ').trim(); }
function regionOf(host){
  if (/\.de$/.test(host)) return 'DE';
  if (/\.(at|ch|eu|nl|fr|it|es|be|dk|se|fi|pl|cz)$/.test(host)) return 'EU';
  return 'INT';
}

const out = [];
for (const it of $input.all()) {
  const j = it.json || {};

  if (Array.isArray(j.hits)) {
    // Hacker News
    for (const h of j.hits) {
      const title = h.title || h.story_title;
      let url = h.url || h.story_url;
      if (!title) continue;
      if (!url) url = 'https://news.ycombinator.com/item?id=' + h.objectID;
      const host = hostOf(url);
      out.push({ json: { url_hash: norm(url), title: String(title).trim(), title_norm: tnorm(title), summary: String(title).trim(), source: host || 'news.ycombinator.com', provider: 'Hacker News', url: String(url), published_at: h.created_at || null, source_type: 'discovery', region: regionOf(host), trust_score: 4 } });
    }
  } else if (Array.isArray(j.results)) {
    // Tavily
    for (const r of j.results) {
      const title = r.title; const url = r.url;
      if (!title || !url) continue;
      const host = hostOf(url);
      out.push({ json: { url_hash: norm(url), title: String(title).trim(), title_norm: tnorm(title), summary: String(r.content || title).slice(0,600), source: host, provider: 'Tavily', url: String(url), published_at: r.published_date || null, source_type: 'search', region: regionOf(host), trust_score: 5 } });
    }
  } else if (Array.isArray(j.items)) {
    // GitHub
    for (const g of j.items) {
      const title = g.full_name; const url = g.html_url;
      if (!title || !url) continue;
      out.push({ json: { url_hash: norm(url), title: String(title).trim(), title_norm: tnorm(title), summary: String(g.description || title).slice(0,600), source: 'github.com', provider: 'GitHub', url: String(url), published_at: g.pushed_at || null, source_type: 'discovery', region: 'INT', trust_score: 4 } });
    }
  } else if (j.title && (j.link || j.id || j.guid)) {
    // RSS - Metadaten kommen bereits angereichert aus 'RSS Eintraege'
    const title = j.title; const url = j.link || j.id || j.guid;
    if (!title || !url) continue;
    const host = hostOf(url);
    out.push({ json: { url_hash: norm(url), title: String(title).trim(), title_norm: tnorm(title), summary: String(j.contentSnippet || j.content || title).slice(0,600), source: host || String(j.feed_source_name || 'RSS'), provider: String(j.feed_source_name || 'RSS'), url: String(url), published_at: j.isoDate || j.pubDate || null, source_type: String(j.feed_source_type || 'news'), region: String(j.feed_region || regionOf(host)), trust_score: (j.feed_trust_score != null ? j.feed_trust_score : 6) } });
  }
}
return out;

