let raw = ($json && $json.text) ? $json.text : (($json && $json.output) ? $json.output : (($json && $json.response && $json.response.text) ? $json.response.text : ''));
let arr = [];
try { arr = JSON.parse(String(raw).replace(/```json/g,'').replace(/```/g,'').trim()); } catch (e) { arr = []; }
const scoreMap = {};
