const PRIO = { handcraft: 2, manufacturing: 2, engineering: 2, sme: 1, automation: 1, regulation: 0, ai_models: -1, comparison: -2 };
const MIN_SCORE = 7;

const out = [];
items.forEach((c, idx) => {
  const r = (scoreMap[c.i] !== undefined) ? scoreMap[c.i] : scoreMap[idx];
  const rawScore = (r && typeof r.score === 'number') ? r.score : 0;
  const category = (r && r.category) ? r.category : '';
  const adj = PRIO[category] !== undefined ? PRIO[category] : 0;
  const eff = Math.max(0, Math.min(10, rawScore + adj));
  if (eff < MIN_SCORE) return;
  const base = orig[idx] ? orig[idx].json : {};
  out.push({ json: Object.assign({}, base, {
    score: eff,
    category: category,
    score_reason: 'roh ' + rawScore + ' | Korridor ' + (category||'-') + ' ' + (adj>=0?'+':'') + adj + ' | effektiv ' + eff
