function txt(v){ if(v==null) return ''; if(typeof v==='string') return v.trim(); if(typeof v==='object' && typeof v._==='string') return v._.trim(); return String(v).trim(); }
function pickLink(l){ if(l==null) return ''; if(typeof l==='string') return l.trim(); if(Array.isArray(l)){ const alt = l.find(x=>x&&x.rel==='alternate') || l.find(x=>x&&x.href) || l[0]; return pickLink(alt); } if(typeof l==='object'){ if(l.href) return String(l.href).trim(); if(l._) return String(l._).trim(); } return ''; }

const MAX_PER_FEED = 30;
const MAX_AGE_DAYS = 10;
