// Feed-Metadaten kommen ueber den Index, NICHT ueber itemMatching().
// itemMatching() liefert auf dieser Instanz null, dadurch landeten BSI (authority/10)
// und Fraunhofer (research/9) bisher als 'vendor' mit Default-Trust in news_memory.
const feeds = $('Nur PRUEFEN ausschliessen').all().map(i => i.json);

const items = $input.all();
const out = [];
for (let idx = 0; idx < items.length; idx++) {
  const j = items[idx].json || {};
  const meta = feeds[idx] || {};
  let channelTitle = meta.source_name || 'RSS';
  let entries = [];
  if (j.rss && j.rss.channel){
    const ch = j.rss.channel;
    if (!meta.source_name) channelTitle = txt(ch.title) || 'RSS';
    let its = ch.item || []; if(!Array.isArray(its)) its=[its];
    entries = its.map(e => ({ title: txt(e.title), link: pickLink(e.link), contentSnippet: txt(e.description || e.summary), isoDate: txt(e.pubDate || e.published || e.updated) || null }));
  } else if (j.feed){
    const fe = j.feed;
    if (!meta.source_name) channelTitle = txt(fe.title) || 'RSS';
    let its = fe.entry || []; if(!Array.isArray(its)) its=[its];
    entries = its.map(e => ({ title: txt(e.title), link: pickLink(e.link), contentSnippet: txt(e.summary || e.content), isoDate: txt(e.updated || e.published) || null }));
  }
  entries = entries.filter(e => e.title && e.link);
  entries = entries.filter(e => { if(!e.isoDate) return true; const t = Date.parse(e.isoDate); if(isNaN(t)) return true; return (now - t) <= MAX_AGE_DAYS*86400000; });
  entries = entries.slice(0, MAX_PER_FEED);
  for (const en of entries){
    out.push({ json: Object.assign({}, en, {
      creator: channelTitle,
      feed_source_name: channelTitle,
      feed_source_type: meta.source_type || 'news',
      feed_corridor: meta.corridor || '',
      feed_region: meta.region || 'INT',
      feed_trust_score: (meta.trust_score != null ? meta.trust_score : 6),
      feed_vendor_bias: !!meta.vendor_bias
    }) });
  }
}
return out;

