  const url = item.url, title = item.title, st = String(item.source_type||'');
  const h = hostOf(url), p = pathOf(url), t = String(title||'').toLowerCase();
  if (!h) return 'keine URL';
  for (const d of domains){ if (h === d || h.endsWith('.' + d)) return 'Domain gesperrt: ' + d; }
  if (/\.(app|ai|io)$/.test(h) && CURATED.indexOf(st) < 0) {
    for (const k of vendorTitle){ if (t.indexOf(k) >= 0) return 'Produktdomain + Verkaufstitel: ' + h; }
  }
  for (const s of paths){ if (p.indexOf(s) >= 0) return 'Verkaufsseite: ' + s; }
  for (const k of titleKw){ if (t.indexOf(k) >= 0) return 'Listicle-Muster: ' + k; }
  if (CURATED.indexOf(st) < 0) {
    for (const k of vendorTitle){ if (t.indexOf(k) >= 0) return 'Verkaufstitel bei nicht-kuratierter Quelle: ' + k; }
  }
  return '';
}

