const rules = $('Blocklist lesen').all().map(i => i.json).filter(r => r && r.pattern);
const domains     = rules.filter(r => r.match_type === 'domain').map(r => String(r.pattern).toLowerCase());
const paths       = rules.filter(r => r.match_type === 'url_path').map(r => String(r.pattern).toLowerCase());
const titleKw     = rules.filter(r => r.match_type === 'title_keyword').map(r => String(r.pattern).toLowerCase());
const vendorTitle = rules.filter(r => r.match_type === 'vendor_title').map(r => String(r.pattern).toLowerCase());

// Kuratierte Quellen (RSS aus content_sources) sind von der
// Verkaufstitel-Heuristik ausgenommen - dort ist 'Software' im Titel
// ein normales Fachthema, kein Verkaufssignal.
const CURATED = ['news','authority','research','vendor'];

function blockReason(item){
  const url = item.url, title = item.title, st = String(item.source_type||'');
  const h = hostOf(url), p = pathOf(url), t = String(title||'').toLowerCase();
  if (!h) return 'keine URL';
  for (const d of domains){ if (h === d || h.endsWith('.' + d)) return 'Domain gesperrt: ' + d; }
  if (/\.(app|ai|io)$/.test(h) && CURATED.indexOf(st) < 0) {
    for (const k of vendorTitle){ if (t.indexOf(k) >= 0) return 'Produktdomain + Verkaufstitel: ' + h; }
  }
  for (const s of paths){ if (p.indexOf(s) >= 0) return 'Verkaufsseite: ' + s; }
  for (const k of titleKw){ if (t.indexOf(k) >= 0) return 'Listicle-Muster: ' + k; }
  if (CURATED.indexOf(st) < 0) {
    for (const k of vendorTitle){ if (t.indexOf(k) >= 0) return 'Verkaufstitel bei nicht-kuratierter Quelle: ' + k; }
  }
  return '';
}

const existing = $('news_memory Keys laden').all();
