const seenTitle = new Set();
for (const it of existing) {
  const j = it.json || {};
  if (j.url_hash) seenHash.add(String(j.url_hash));
  if (j.title_norm) seenTitle.add(String(j.title_norm));
}

const out = [];
const blockedLog = [];
for (const it of $('Normalisieren und Hash').all()) {
  const j = Object.assign({}, it.json);
  const uh = String(j.url_hash || '');
  const tn = String(j.title_norm || '');
  if (!uh) continue;
  const reason = blockReason(j);
  if (reason) { blockedLog.push(hostOf(j.url) + ' -> ' + reason); continue; }
  if (seenHash.has(uh)) continue;
  if (tn && seenTitle.has(tn)) continue;
  seenHash.add(uh);
  if (tn) seenTitle.add(tn);
  j.published_at = toIso(j.published_at);
  out.push({ json: j });
}
if (out.length) { out[0].json.blocked_log = blockedLog.slice(0,40).join(' | '); out[0].json.blocked_count = blockedLog.length; }
return out;
